WITH filtered_store_sales AS (SELECT *, LAST_DAY(sale_date) AS sale_date_month_end FROM store_sales WHERE sale_date BETWEEN '2023-04-01' AND '2024-08-01' AND product_id IN (1, 4)), Agg AS (SELECT product_id, COUNT(DISTINCT revenue) AS unique_products, COUNT(units) AS units_count FROM filtered_store_sales GROUP BY product_id) SELECT * FROM Agg ORDER BY units_count DESC, product_id DESC LIMIT 5
